    if (parenString[i] == '(') {
      depth++;
    } else if (parenString[i] == ')') {
      depth--;
    }

    // When a closing parenthesis is encountered, the current depth indicates 
    // how many nested layers are active. So we add this to our result list.
    if (parenString[i] == ')' && depth >= 0) {
      result.add(depth);
    }
  }

  return result;
}
