  int currentDepth = 0;

  for (int i = 0; i < parenString.length; ++i) {
    if (parenString[i] == '(') {
      currentDepth++;
    } else if (parenString[i] == ')') {
      currentDepth--;
    }

    // When we see a closing parenthesis, record the depth at that moment
    if (parenString[i] == ')') {
      result.add(currentDepth);
    }
  }

  return result;
}
