int _findMatchingIndex(String s, int start, charToFind, bool isLeftParen) {
  int count = 0;
  for (int i = start; i < s.length; ++i) {
    if (s[i] == charToFind) {
      if (isLeftParen ? (count++ > 0) : --count == 0) {
        return i;
      }
    }
  }
  throw FormatException('Unmatched $charToFind');
}

// Helper function to split nested parentheses by groups and add their positions
void _splitByGroups(String s, int start, List<int> result) {
  int currentDepth = 0;
  int startIdx = start;

  for (int i = start; i < s.length; ++i) {
    if (s[i] == '(') {
      currentDepth++;
    } else if (s[i] == ')') {
      currentDepth--;
      if (currentDepth == 0) {
        result.add(i + 1);
        break;
      }
    }
  }
