List<int> parseNestedParens(String parenString) {
  final List<int> result = [];
  int depth = 0;

  for (int i = 0; i < parenString.length; ++i) {
    if (parenString[i] == '(') {
      depth++;
    } else if (parenString[i] == ')') {
      depth--;
    }

    // Check if the current character is a digit and not part of an escaped one
    if (depth > 0 && !isEscaped(i, parenString)) {
      if (RegExp(r'[0-9]').hasMatch(parenString[i])) {
        result.add(int.parse(parenString[i]));
      }
    }
  }

  return result;
}

bool isEscaped(int index, String str) {
  if (index <= 0) return false;

  bool escapeNext = false;
  for (int i = index - 1; i >= 0; --i) {
    if (str[i] == '\\') {
      escapeNext = true;
      break;
    }
  }

  return escapeNext;
}
