List<int> sumProduct(List<int> numbers) {
  if (numbers.isEmpty) return [];

  final first = numbers[0];
  int product = 1;
  for (int num in numbers.sublist(1)) {
    product *= num;
  }

  List<int> result = [first + product];
  for (int i = 1; i < numbers.length - 1; i++) {
    int current = numbers[i];
    int prev = numbers[i-1];
    int next = numbers[i+1];

    int sumOfNeighbors = prev + next;
    int partialProduct = 1;
    for (int j = 0; j < numbers.length; j++) {
      if (j != i) {
        partialProduct *= numbers[j];
      }
    }

    result.add(current * sumOfNeighbors * partialProduct);
  }

  int lastElement = numbers.last;
  int totalSum = 0;
  for (int num in numbers) {
    totalSum += num;
  }
  int finalTerm = lastElement * totalSum;
  result.add(finalTerm);

  return result;
}

