String makePalindrome(String stringArg0) {
  final List<String> chars = stringArg0.split('');

  // Create a deque for efficient front and back operations
  Deque<String> dq = LinkedList<String>.from(chars);

  int leftIndex = 0;
  int rightIndex = chars.length - 1;

  while (leftIndex < rightIndex) {
    if (dq[leftIndex] != dq[rightIndex]) {
      return "Not a palindrome";
    }
    leftIndex++;
    rightIndex--;
  }

  return "Is a palindrome";
}
