String makePalindrome(String stringArg0) {
  List<String> chars = stringArg0.split('');
  int left = 0;
  int right = chars.length - 1;

  while (left < right) {
    if (chars[left] != chars[right]) {
      // Find the nearest matching character on the right side
      bool foundMatch = false;
      for (int i = right; i > left; i--) {
        if (chars[i] == chars[left]) {
          chars[right] = chars[i];
          foundMatch = true;
          break;
        }
      }

      if (!foundMatch) {
        return 'Not possible';
      }
    }
    left++;
    right--;
  }

  return chars.join(''); 
