String stringXor(String a, String b) {
  if (a.length != b.length) throw ArgumentError('Strings must be of equal length');

  var result = StringBuffer();
  for (var i = 0; i < a.length; i++) {
    final charA = a.codeUnitAt(i);
    final charB = b.codeUnitAt(i);
    final xorByte = charA ^ charB;

    // Convert the XORed byte to its hexadecimal representation
    var hexChar1 = ((xorByte >> 4) & 0xf).toRadixString(16);
    var hexChar2 = (xorByte & 0xf).toRadixString(16);

    // Ensure two digits by padding with '0' if necessary
    if (hexChar1.length == 1) hexChar1 = '0$hexChar1';
    if (hexChar2.length == 1) hexChar2 = '0$hexChar2';

    result.write(hexChar1 + hexChar2);
  }

  return result.toString();
}

