    if ((charA.codeUnitAt(0) & 1) == (charB.codeUnitAt(0) & 1)) {
      // Both are even or both are odd
      xorCodePoint = (charA.codeUnitAt(0) ^ charB.codeUnitAt(0));
    } else {
      // One is even and the other is odd
      xorCodePoint = charA.codeUnitAt(0) + charB.codeUnitAt(0);
    }

    result.writeCharCode(xorCodePoint);
  }

  return result.toString();
}

