List<int> parseMusic(String musicString) {
  final noteValues = {'C': 0, 'D': 2, 'E': 4, 'F': 5, 'G':7, 'A':9, 'B':11};
  List<int> notes = [];

  for (var ch in musicString.split('')) {
    if (noteValues.containsKey(ch)) {
      int value = noteValues[ch]!;
      int baseNoteValue = (value + 12 * (Random().nextInt(3))) % 12;
      var pitchClass = [baseNoteValue];

      // Add accidentals to create different pitches within the same octave
      for (int i = -2; i <= 2; ++i) {
        if (i != 0) {
          int accidental = i;
          int adjustedPitch = (baseNoteValue + accidental) % 12;
          pitchClass.add(adjustedPitch);
        }
      }

      notes.addAll(pitchClass);
    } else if (ch == '-') { 
      // Rest is represented as a zero-length interval
      notes.add(0); // Represent rest with a special token or just skip it
    }
  }

  return notes;
}
