List<int> parseMusic(String musicString) {
  List<int> notes = [];
  int currentNote = 0;

  for (int i = 0; i < musicString.length; i++) {
    if (musicString[i] == ' ') continue;

    switch (musicString[i]) {
      case '-':
        currentNote -= 12;
        break;
      case '+':
        currentNote += 12;
        break;
      default:
        // Check if the character is a digit or letter
        if ('A' <= musicString[i].toUpperCase() && musicString[i].toUpperCase() <= 'G') {
          currentNote += getNoteValue(musicString[i]);
        } else if ('1' <= musicString[i] && musicString[i] <= '9') {
          currentNote += int.parse(musicString[i]);
        }
        break;
    }
    notes.add(currentNote);
  }

  return notes;
}

int getNoteValue(String noteChar) {
  final noteValues = {'C': 0, 'D': 2, 'E': 4, 'F':5, 'G':7, 'A':9, 'B':11};
  return noteValues[noteChar.toUpperCase()] ?? 0;
}
