import 'dart:math';

List<int> parseMusic(String musicString) {
  final List<String> notes = ['C', 'D', 'E', 'F', 'G', 'A', 'B'];

  int currentNoteIndex = 0;
  List<int> result = [];

  for (int i = 0; i < musicString.length; i++) {
    String c = musicString[i];

    if (c == '-') {
      // Note is not played, skip it
      continue;
    } else if (c == '#') {
      // Sharpen the note
      currentNoteIndex++;
      if (currentNoteIndex >= notes.length) {
        currentNoteIndex = 0;
      }
    } else if (c == 'b') {
      // Flatten the note
      currentNoteIndex--;
      if (currentNoteIndex < 0) {
        currentNoteIndex = notes.length - 1;
      }
    } else {
      // Regular note character
      int index = notes.indexOf(c);
      if (index != -1) {
        currentNoteIndex = index;
      }
    }

    // Add the pitch of the note to the result list
    result.add(currentNoteIndex + 1); // Pitch values are 1-indexed
  }

  return result;
}
