import 'dart:math';

List<int> parseMusic(String musicString) {
  final notes = <int>[];
  var i = 0;

  while (i < musicString.length) {
    if (musicString[i] == '(') {
      int count = 0;
      int j = i + 1;
      while (j < musicString.length && musicString[j] != ')') {
        count++;
        j++;
      }
      for (var k = 0; k < count; k++) {
        notes.add(0);
      }
      i = j + 1;
    } else if (musicString[i] == 'x' || musicString[i] == 'X') {
      // Parse the number of beats following x/X
      int duration = 0;
      int j = i + 1;
      while (j < musicString.length && RegExp(r'[0-9]').hasMatch(musicString[j])) {
        duration *= 10;
        duration += int.parse(musicString[j]);
        j++;
      }
      notes.addAll(List.filled(duration, 1));
      i = j;
    } else if (musicString[i] == 'o' || musicString[i] == 'O') {
      // Parse the number of beats following o/O
      int duration = 0;
      int j = i + 1;
      while (j < musicString.length && RegExp(r'[0-9]').hasMatch(musicString[j])) {
        duration *= 10;
        duration += int.parse(musicString[j]);
        j++;
      }
      notes.addAll(List.filled(duration, -1));
      i = j;
    } else if (musicString[i].isDigit()) {
      // Handle single digit note values
      int value = int.parse(musicString[i]);
      notes.add(value);
      i++;
    } else {
      // Skip other characters or invalid input
      i++;
    }
  }

  return notes;
}
