  final List<String> tokens = [];
  for (int i = 0; i < musicString.length; i++) {
    String token = '';
    if (musicString[i] == ' ') {
      continue;
    }

    while (i < musicString.length && ![' ', '\n', '\t'].contains(musicString[i])) {
      token += musicString[i];
      i++;
    }
    tokens.add(token);
  }

  final List<int> result = [];

  for (final token in tokens) {
    var noteName = token;
    int octave = currentOctave;
    int accidentals = 0;

    // Check for accidental modifiers like # or b
    if (noteName.endsWith('#')) {
      accidentals = 1;
      noteName = noteName.substring(0, noteName.length - 1);
    } else if (noteName.endsWith('b')) {
      accidentals = -1;
      noteName = noteName.substring(0, noteName.length - 1);
    }

    // Find the index of the note name in the list of notes
    final index = notes.indexOf(noteName);

    if (index != -1) {
      // Calculate the actual pitch value based on the note index and accidentals
      int basePitchValue = index + 24 + (currentOctave * 12); // C4 is MIDI note number 60, so starting from C3=48
      final adjustedPitchValue = basePitchValue + accidentals;

      // Adjust the octave if necessary based on the note's position
      final noteRange = [9, 17]; // C to B across an octave
      final midiNoteNumber = ((adjustedPitchValue % 12) + 12) % 12;
      final effectiveOctave = (adjustedPitchValue ~/ 12).toString();

      // Determine new octave based on where it lands within the scale
      if (midiNoteNumber >= 9) { // If it falls beyond B natural (which is at 11)
        octave += 1;
      } else if (midiNoteNumber <= 0) { // If it falls before C natural
        octave -= 1;
      }

      result.add((octave * 12) + midiNoteNumber);
    } else {
      // Handle octaves explicitly when they're specified with numbers
      try {
        if (token.contains('.')) {
          final parts = token.split('.');
          noteName = parts[0].trim().toUpperCase();
          octave = int.parse(parts[1]);
        } else {
          octave = int.tryParse(token.trim()) ?? currentOctave;
        }

        final index = notes.indexOf(noteName);
        if (index != -1) {
          final midiNoteNumber = (index + 24 + octave * 12) % 12;
          result.add((octave * 12) + midiNoteNumber);
        }
      } catch (_) {}
    }
  }

  return result;
}
