String sortNumbers(String numbers) {
  List<int> nums = numbers.split(' ').map(int.parse).toList();

  // Bubble Sort implementation for sorting the list of integers
  int n = nums.length;
  bool swapped;
  do {
    swapped = false;
    for (int i = 0; i < n - 1; i++) {
      if (nums[i] > nums[i + 1]) {
        int temp = nums[i];
        nums[i] = nums[i + 1];
        nums[i + 1] = temp;
        swapped = true;
      }
    }
    n--;
  } while (swapped);

  return nums.join(' ');
}
