  int mid = ((left + right) / 2).toInt();

  while (right - left > 1) {
    var currentMidVal = numbers[mid];

    if (currentMidVal >= numbers[right]) {
      left = mid.toDouble();
    } else if (currentMidVal < numbers[left] && 
               currentMidVal <= numbers[right]) {
      right = mid.toDouble();
    }

    mid = ((left + right) / 2).toInt();
  }

  // Now check the elements at [mid] and [mid+1]
  List<int> indicesToCompare = [];
  for (int i in [mid, mid+1]) {
    if (i < numbers.length) indicesToCompare.add(i);
  }

  // Sort by absolute difference from target
  indicesToCompare.sort((a, b) => 
    (abs(numbers[a] - numbers[mid]) - abs(numbers[b] - numbers[mid])).sign);

  return indicesToCompare.map((i) => numbers[i]).toList();  
