  while (left < right) {
    final mid = (left + right) ~/ 2;
    if (numbers[mid] < target) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }

  List<double> result = [numbers[left], numbers[right]];

  // Check for duplicates
  if (result[0] == result[1]) return result;

  return result;
}

