List<double> findClosestElements(List<double> numbers) {
  if (numbers.isEmpty || numbers.length == 1) return List.from(numbers);

  double target = numbers[0];
  int closestIndex = 0;

  for (int i = 1; i < numbers.length; i++) {
    final diffCurrent = abs(target - numbers[i]);
    final diffClosest = abs(target - numbers[closestIndex]);

    if (diffCurrent < diffClosest) {
      closestIndex = i;
    } else if (diffCurrent == diffClosest && numbers[i] > numbers[closestIndex]) {
      closestIndex = i;
    }
  }

  return [numbers[closestIndex]];
}

List<double> findClosestElements(List<double> numbers) {
  if (numbers.isEmpty || numbers.length == 1) return numbers;

  double target = numbers[0];
  int left = 0, right = numbers.length - 1;

  while (left < right) {
    final mid = (left + right) ~/ 2;

    // Check for possible closest elements
    if (numbers[mid] < target) {
      left = mid + 1;
    } else if (numbers[mid] > target) {
      right = mid;
    } else {
      break; // Found the exact match
    }
  }

  // Now check which of [left-1, left] is closer to target
  List<double> result = [];
  if (left >= 1 && left < numbers.length) {
    result.add(numbers[left - 1]);
    result.add(numbers[left]);
  } else if (left == 0) {
    result.add(numbers[0]);
  } else { 
    result.add(numbers[right]); 
  }

  return result;
}

