int largestDivisor(int n) {
  if (n == 0 || n == 1) return 1;

  int maxFactor = 1;
  for (var i = 2; i <= sqrt(n); i++) {
    if (n % i == 0) {
      maxFactor = max(maxFactor, i);
      maxFactor = max(maxFactor, n ~/ i);
    }
  }

  // Check if the number itself is a prime and greater than 1.
  if (maxFactor < 2 && n > 1) {
    return n;
  } else if (maxFactor >= 2 && n % maxFactor != 0) {
    return maxFactor;
  } else {
    return maxFactor;
  }
}
