List<int> sortThird(List<int> l) {
  final n = l.length;
  if (n == 0 || n < 3) return List.from(l);

  // Create a list to hold the sorted third elements
  final thirdElements = List<int>.filled(n, -1);

  for (int i = 0; i < n; i++) {
    int indexInThirdGroup = i % 3;
    thirdElements[indexInThirdGroup] = l[i];
  }

  // Sort the thirdElements in ascending order
  thirdElements.sort();

  // Replace every third element with the corresponding value from the sorted list
  for (int i = 0; i < n; i++) {
    int indexInThirdGroup = i % 3;
    l[i] = thirdElements[indexInThirdGroup];
  }

  return l;
}

