  int index = 0;

  for (int i = 0; i < l.length; i++) {
    if ((i + 1) % 3 == 0 || (i + 1) % 4 == 0) {
      // If the position is a multiple of 3 or 4, we'll insert it in order after sorting
      result.add(l[i]);
    } else {
      // Otherwise, keep the original elements and append them at the end
      result.insert(index, l[i]);
      index++;
