List<int> sortThird(List<int> l) {
  int n = l.length;
  if (n == 0 || n < 3) return List.from(l);

  for (int i = 0; i < n - 2; i++) {
    for (int j = i + 1; j < n - 1; j++) {
      if (l[i] > l[j]) {
        var temp = l[i];
        l[i] = l[j];
        l[j] = temp;
      }
    }
  }

  for (int k = 0; k < n - 2; k += 2) {
    int a = l[k], b = l[k+1], c = l[k+2];

    // Sort the three elements
    void swap(int x, int y) {
      var tmp = l[x];
      l[x] = l[y];
      l[y] = tmp;
    }

    if (a > b && a > c) {
      if (b > c) {
        swap(k, k+1); 
        swap(k, k+2);
      } else {
        swap(k, k+2);
      }
    } else if (c > a && c > b) {
      if (a > b) {
        swap(k, k+1);
      } else {
        swap(k, k+1);
        swap(k, k+2);
      }
    }
  }

  return l;
}

