List<int> sortThird(List<int> l) {
  if (l.length < 3) return List.from(l);

  final n = l.length;
  for (int i = 0; i < n - 2; i += 3) {
    int j = i + 2;
    while (j > i && l[j] < l[i]) {
      swap(l, j, j-1);
      j--;
    }
  }

  return l;
}

void swap(List<int> list, int a, int b) {
  var temp = list[a];
  list[a] = list[b];
  list[b] = temp;
