  for (int i = 1; i <= n; i++) {
    bool isFizz = i % 3 == 0;
    bool isBuzz = i % 5 == 0;
    if (!isFizz && !isBuzz) {
      count++;
    } else if (isFizz && isBuzz) {
      print('FizzBuzz');
    } else if (isFizz) {
      print('Fizz');
