  positions.sort();
  directions.shuffle(); // Shuffle directions after sorting

  // Simulate movement until collision occurs
  while (true) {
    var collisions = false;

    for (var i = 0; i < totalCars - 1; i++) {
      // Check adjacent cars in opposite directions
      if ((directions[i] == 1 && directions[i + 1] == -1)) {
        if (positions[i + 1] == positions[i]) {
          return 1; // Collision occurred
        }
      }
    }

    // Move all cars forward
    for (var i = 0; i < totalCars; i++) {
      positions[i] += directions[i];

      // If a car goes out of bounds, it's removed
      if (positions[i] <= 0 || positions[i] > 1000000) {
        directions.removeAt(i);
        positions.removeAt(i);
        i--; // Adjust index due to removal
        collisions = true;
      }
    }

    if (!collisions) break;
  }

