String changeBase(int x, int base) {
  if (base < 2 || base > 36) throw ArgumentError('Base must be between 2 and 36');

  final digits = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  List<String> result = [];

  if (x == 0) return '0';

  while (x > 0) {
    final remainder = x % base;
    result.add(digits[remainder]);
    x ~/= base;
  }

  result.reversed.join();
}

