import 'dart:collection';
import 'dart:math';

class BracketValidator {
  bool validateBrackets(String input) {
    final stack = Stack<String>();
    final opening = ['(', '{', '['];
    final closing = [')', '}', ']'];

    for (var char in input.split('')) {
      if (opening.contains(char)) {
        stack.add(char);
      } else if (closing.contains(char)) {
        if (stack.isEmpty || !isOpenMatching(stack.removeLast!, char)) {
          return false;
        }
      }
    }

    return stack.isEmpty;
  }

  bool isOpenMatching(String open, String close) {
    final Map<String, String> mapping = {
      '(': ')',
      '[': ']',
      '{': '}'
    };
    return mapping[open] == close;
  }
}

void main() {
  // Test cases
  print(BracketValidator().validateBrackets("({[]})")); // true
  print(BracketValidator().validateBrackets("([)]"));   // false
  print(BracketValidator().validateBrackets("{[(])}")); // false
  print(BracketValidator().validateBrackets("(())((()))(())")); // true
  print(BracketValidator().validateBrackets("("));       // false
}
