  var valid = true;

  for (int codeUnit in chars) {
    if (codeUnit >= _charValues[0] && codeUnit <= _charValues[1] + 26) {
      var value = codeUnit - _charValues[1];
      if (value < 32) {
        switch (value) {
          case 0:
            bracketBalance += 1;
            break;
          case 1:
            bracketBalance -= 1;
            if (bracketBalance < 0) {
              valid = false;
              break;
            }
            break;
          default:
            valid = false;
        }
      } else if (value > 32) {
        valid = false;
      }
    } else {
      valid = false;
    }

    if (!valid) break;
  }

  return bracketBalance * 10 + (valid ? 1 : 0);
}

