bool monotonic(List<num> l) {
  if (l.isEmpty || l.length == 1) return true;

  bool increasing = false;
  bool decreasing = false;

  for (int i = 0; i < l.length - 1; i++) {
    num a = l[i];
    num b = l[i + 1];

    if (a < b) {
      decreasing = false;
    } else if (a > b) {
      increasing = false;
    }

    if (!increasing && !decreasing) {
      // If both are not set, check the direction based on first comparison
      if (a < b) {
        increasing = true;
      } else if (a > b) {
        decreasing = true;
      }
    }

    // If it's neither strictly increasing nor decreasing at this point, break early
    if (increasing && decreasing) {
      return false;
    }
  }

  return true;
}
