import 'dart:collection';
import 'dart:io';

class BracketChecker {
  static bool checkBrackets(String input) {
    if (input.isEmpty) return true;

    final stack = Stack<String>();

    for (var i = 0; i < input.length; i++) {
      var ch = input[i];

      switch(ch) {
        case '(':
        case '[':
        case '{':
          stack.add(ch);
          break;

        case ')':
          if (stack.isNotEmpty && stack.last == '(') {
            stack.pop();
          } else {
            return false;
          }
          break;

        case ']':
          if (stack.isNotEmpty && stack.last == '[') {
            stack.pop();
          } else {
            return false;
          }
          break;

        case '}':
          if (stack.isNotEmpty && stack.last == '{') {
            stack.pop();
          } else {
            return false;
          }
          break;

        default:
          // Ignore other characters
      }
    }

    return stack.isEmpty;
  }
}

// Example usage:
void main() {
  print(BracketChecker.checkBrackets("({[]})"));   // true
  print(BracketChecker.checkBrackets("{[}]);"));   // false
  print(BracketChecker.checkBrackets("(]"));       // false
  print(BracketChecker.checkBrackets("([)]"));     // false
  print(BracketChecker.checkBrackets("([]{})"));   // true
  print(BracketChecker.checkBrackets(""))          // true
}
