bool correctBracketing(String brackets) {
  if (brackets.isEmpty) return true;

  final stack = <String>[];
  for (int i = 0; i < brackets.length; i++) {
    String char = brackets[i];

    if (char == '(' || char == '[' || char == '{') {
      stack.add(char);
    } else {
      if (stack.isEmpty) return false;

      String lastOpen = stack.removeLast();
      bool match = false;
      switch (lastOpen) {
        case '(':
          match = char == ')';
          break;
        case '[':
          match = char == ']';
          break;
        case '{':
          match = char == '}';
          break;
      }

      if (!match) return false;
    }
  }

  return stack.isEmpty;
}
