List<num> derivative(List<num> xs) {
  final n = xs.length;
  List<num> result = List.filled(n - 1, 0);

  for (int i = 0; i < n - 1; i++) {
    num x = xs[i];
    num h = 1e-5;

    // Use central difference formula: f'(x) ≈ [f(x + h) - f(x - h)] / (2h)
    num forward = evaluateFunction(xs, x + h);
    num backward = evaluateFunction(xs, x - h);

    result[i] = (forward - backward) / (2 * h);
  }

  return result;
}

num evaluateFunction(List<num> xs, num x) {
  int index = findClosestIndex(xs, x);
  if (index == -1 || index >= xs.length) {
    throw StateError('No matching value found in the list.');
  }
  return xs[index];
}

int findClosestIndex(List<num> xs, num target) {
  int left = 0;
  int right = xs.length - 1;
  int closestIndex = -1;
  double minDifference = double.infinity;

  while (left <= right) {
    int mid = (left + right) ~/ 2;
    num current = xs[mid];
    num diff = current - target;

    if (diff.abs() < minDifference) {
      minDifference = diff.abs();
      closestIndex = mid;
    }

    if (current < target) {
      left = mid + 1;
    } else {
