int findClosestIndex(List<num> xs, num target) {
  int left = 0;
  int right = xs.length - 1;
  int closestIndex = -1;
  double minDifference = double.infinity;

  while (left <= right) {
    int mid = (left + right) ~/ 2;
    num current = xs[mid];
    num diff = current - target;

    if (diff.abs() < minDifference) {
      minDifference = diff.abs();
      closestIndex = mid;
    }

    if (current < target) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  return closestIndex;
}

