String circularShift(int x, int shift) {
  if (x == 0 || shift % 32 == 0) return '0';

  // Convert to binary string with leading zeros for fixed length of 8 bits
  String bin = x.toString(2).padLeft(8, '0');

  // Calculate effective shift amount within the 8-bit range
  int effectiveShift = shift % 8;

  if (effectiveShift > 0) {
    // Right rotate by effectiveShift positions
    String shiftedBin = bin.substring(bin.length - effectiveShift) + 
                      bin.substring(0, bin.length - effectiveShift);

    // Convert back to integer and then to string in hex format
    int resultInt = int.parse(shiftedBin, radix: 2);
    return resultInt.toRadixString(16).toUpperCase();
  } else {
    // Left rotate by (-effectiveShift) positions which is same as right shifting
    int leftShiftAmount = 8 - effectiveShift;
    String shiftedBin = bin.substring(leftShiftAmount) + 
                      bin.substring(0, leftShiftAmount);

    int resultInt = int.parse(shiftedBin, radix: 2);
    return resultInt.toRadixString(16).toUpperCase();
  }
}
