  int numBits = x.toString(2).length;

  // Calculate effective shift amount within the bit length
  int effectiveShift = shift % numBits;

  if (effectiveShift == 0) return x.toRadixString(2);

  String binStr = x.toString(2);
  List<String> bits = binStr.split('');

  // Perform right rotation by effectiveShift positions
  for (int i = 0; i < effectiveShift; i++) {
