    for (var j = i - 1; j >= 0 && s[j] == s[i]; j--) {
      c++;
    }
    counts.add(c);
  }

  int total = 0;
  for (var count in counts) {
    if (count > 0) {
      total += count * (count + 1) ~/ 2;
    }
  }

  while (total > n) {
    // Find the largest possible reduction to make it divisible by n
    for (var i = 0; i < counts.length; i++) {
      if (counts[i] > 0) {
        final reduceBy = (counts[i] * (counts[i] + 1) ~/ 2) % n;
        if (reduceBy != 0) {
          counts[i]--;
          total -= reduceBy;
          break;
        }
      }
    }
  }

  return total;
}
