import 'dart:math';

int fruitDistribution(String s, int n) {
  if (s.isEmpty || n <= 0) return -1;

  final List<int> counts = [0];
  for (var c in s.split('')) {
    var index = int.parse(c);
    if (index < 0 || index >= counts.length) continue;
    counts[index]++;
  }

  while (counts.length > 1) {
    var minIndex = findMinIndex(counts);
    if (minIndex == -1) break; // no more fruits to distribute

    var count = counts[minIndex];
    var remainingFruits = n % count;

    if (remainingFruits != 0) {
      var tempCount = counts[minIndex] / remainingFruits;
      for (var i in 0; i < counts.length; ++i) {
        counts[i] /= tempCount;
      }

      remainingFruits -= count * tempCount;
    } else {
      remainingFruits = count;
    }

    n -= remainingFruits;
    counts.removeAt(minIndex);
  }

  return n;
}

int findMinIndex(List<int> list) {
  int? minIndex;
  for (var i = 0; i < list.length; ++i) {
    if (list[i] == 0) continue;
    if (minIndex == null || list[i] < list[minIndex]) {
      minIndex = i;
    }
  }
  return minIndex ?? -1;
}
