int smallestChange(List<int> arr) {
  int n = arr.length;
  if (n < 2) return 0;

  // Find the index of minimum element in the array
  int minIndex = 0;
  for (int i = 1; i < n; ++i)
    if (arr[i] < arr[minIndex]) 
      minIndex = i;

  // Compute prefix sum and suffix sum arrays
  List<int> prefixSums = [0];
  for (int i = 0; i < n - 1; ++i)
    prefixSums.add(prefixSums.last + arr[i]);

  List<int> suffixSums = [0];
  for (int i = n - 1; i > 0; --i)
    suffixSums.add(suffixSums.last + arr[i]);

  // Reverse suffix sums to align with original indices
  suffixSums = suffixSums.reversed.toList();

  // Calculate total sum
  int totalSum = prefixSums[n-1];

  // Initialize answer as a large number
  int ans = Int32List.maxElementValue;

  // Try all possible split points after minIndex
  for (int i = minIndex; i < n - 1; ++i) {
    int leftSum = prefixSums[i];   // Sum from start to current position (exclusive)
    int rightSum = totalSum - leftSum;   // Sum from current position to end
    int diff = abs(leftSum - rightSum);
    ans = min(ans, diff);
  }

  return ans;
}
