String stringToChars(String s) {
  List<int> result = [];
  int currentCharCode = 0;

  for (var c in s.split('')) {
    currentCharCode += c.codeUnitAt(0);
    result.add(currentCharCode);
  }

  String finalStr = '';
  for (var code in result) {
    finalStr += code.toString();
  }

  return finalStr;
}

String uniqueDigitsOnly(String str) {
  Set<String> seen = {};
  String output = '';

  for (var ch in str.split('')) {
    if (!seen.contains(ch)) {
      seen.add(ch);
      output += ch;
    }
  }

  return output;
}

String removeNonDigits(String input) {
  String result = '';
  for (var char in input.split('')) {
    if (char.codeUnitAt(0).toString().isNotEmpty && char.codeUnitAt(0).toString()[0] >= '0' && 
        char.codeUnitAt(0).toString()[0] <= '9') {
      result += char;
    }
  }
  return result;
}

List<int> getUniqueIntsFromText(String text) {
  var words = text.replaceAll(RegExp(r'[^\w\s\d]+'), '').split(' ').where((word) => word.isNotEmpty).toList();

  List<int> numbers = [];

  for (var w in words) {
    try {
      int num = int.parse(w);
      numbers.add(num);
    } catch (_) {}
  }

  List<int> uniqueNumbers = [];
  for (var num in numbers) {
    if (!uniqueNumbers.contains(num)) {
      uniqueNumbers.add(num);
    }
  }

  uniqueNumbers.sort(); 

