bool anyInt(dynamic x, dynamic y, dynamic z) {
  if (x is int && y is int && z is int) {
    return true;
  }

  // Check for at least one integer among the three values
  final hasInteger = [x, y, z].any((v) => v is int);

  // If there's exactly one or more integers, check if they are consecutive
  if (!hasInteger || hasInteger && !([x, y, z].whereType<int>().length >= 2)) {
    return false; // Not enough integers to form a sequence
  }

  // Extract all integers from the list
  List<int> ints = [x, y, z].whereType<int>().toList();

  // Sort them and check if they form a consecutive sequence with no gaps
  ints.sort(); // Sorts in ascending order

  // Check that each number is exactly one greater than the previous
  bool isConsecutive = true;
  for (int i = 1; i < ints.length; i++) {
    if (ints[i] != ints[i - 1] + 1) {
      isConsecutive = false;
      break;
    }
  }

  return isConsecutive;
}
