    if (key is String && key.isNotEmpty) {
      bool allLowercase = key.toLowerCase() == key;
      bool allUppercase = key.toUpperCase() == key;

      // If the key is not entirely lowercase or uppercase, it's mixed case which is invalid
      if (!allLowercase && !allUppercase) {
        return false;
      }

      // If the value is a map, recursively check its casing
      if (value is Map) {
        if (!checkDictCase(value)) {
          return false;
        }
      } else if (value is List) {
        for (var item in value) {
          if (item is Map) {
            if (!checkDictCase(item)) {
              return false;
            }
          }
        }
      }
    }
  }

  return true;
