  bool isNegative = value[0] == '-';

  // Remove optional leading '+' or '-' sign and any whitespace
  String numStr = value.trim();
  if (numStr.startsWith('-') || numStr.startsWith('+')) {
    numStr = numStr.substring(1);
  }

  // Split into integer and fractional parts
  final List<String> parts = numStr.split('.');
  var integerPart = parts[0];
  var fractionalPart = parts.length > 1 ? parts[1] : '';

  // Convert integer part to an integer
  int integerValue = int.parse(integerPart);

  // Handle cases where there's a fractional part
  if (fractionalPart.isNotEmpty) {
    double decimalValue = 0.0;

    // Calculate the decimal value of the fractional part
    for (var i = 0; i < fractionalPart.length && i < 3; ++i) {
      if (i >= fractionalPart.length) break;
      final digit = int.parse(fractionalPart[i]);
      decimalValue += digit * pow(10, -(i + 1));
    }

    // If the first digit after decimal is 5 or more, round up
    if (decimalValue >= 0.5) {
      integerValue++;
    }
  } else {
    // No fractional part, just take the integer value as-is
    return integerValue;
  }

  // Apply the negative sign if needed
  return isNegative ? -integerValue : integerValue;
}
