int closestInteger(String value) {
  final parts = value.split('.');
  if (parts.length == 1) return int.parse(parts[0]);

  // Split into integer and fractional part
  final integerPart = parts[0];
  final fractionalPart = parts[1];

  // Check if the fractional part is all zeros or not
  bool hasNonZeroFractionalDigits = false;
  for (var ch in fractionalPart.characters) {
    if (ch != '0') {
      hasNonZeroFractionalDigits = true;
      break;
    }
  }

  if (!hasNonZeroFractionalDigits) {
    return int.parse(integerPart);
  } else {
    // If there are non-zero digits, round based on the first digit of the fractional part
    var roundingDigit = fractionalPart.characters.first;

    switch (roundingDigit) {
      case '5':
        return int.parse(integerPart) + 1;

      default:
        if (int.parse(roundingDigit) < 5) {
          return int.parse(integerPart);
        } else {
          return int.parse(integerPart) + 1;
        }
    }
  }
}

