  for (var i = 0; i < decimalPart.length; i++) {
    if (i >= 6) break; // Limit to up to six digits after decimal point as per Dart's int.fromDouble behavior
    fractionalValue += int.parse(decimalPart[i]) / (pow(10, i + 1));
