List<String> wordsString(String s) {
  final List<String> result = [];

  int i = 0;
  while (i < s.length) {
    if (s[i] == ' ') {
      i++;
      continue;
    }

    int start = i;
    while (i < s.length && !isWordChar(s[i])) {
      i++;
    }

    // Check for possible word boundary after the loop
    bool isEndOfWord = false;
    if (i >= s.length || !isWordChar(s[i])) {
      isEndOfWord = true;
    } else {
      // If there's a character, check if it's part of the same word or not.
      // For example: "hello,world" -> split on comma
      if (!isWordChar(s[i])) {
        isEndOfWord = true;
      }
    }

    if (isEndOfWord) {
      String word = s.substring(start, i);
      result.add(word);
    } else {
      // Handle cases like when we are at end of string and current char is a valid word char
      // e.g., "word"
      if (start != i) { 
        result.add(s.substring(start, i));
      }
    }

    i++; // Move to next position
  }

  return result;
}

bool isWordChar(String c) => c.codeUnitAt(0).toLowerCase() ~/ 128 <= 255; // Assuming ASCII characters only
