List<String> wordsString(String s) {
  final List<String> result = [];
  int i = 0;

  while (i < s.length) {
    if (s[i] == ' ') {
      // Skip spaces between words
      i++;
    } else if (s[i] == '\t') {
      // Skip tabs between words
      i++;
    } else if (s[i] == '\n') {
      // Skip newlines, which are treated as word separators
      i++;
    } else {
      // Found a non-whitespace character: start of a new word
      int j = i + 1;
      while (j < s.length && !isWhitespace(s[j])) {
        j++;
      }

      result.add(s.substring(i, j));
      i = j;
    }
  }

  return result;
}

