List<int> f(int n) {
  if (n == 0 || n == 1) return [1];

  List<int> dp = [1, 1];
  for (int i = 2; i < n + 1; ++i) {
    int sum = 0;
    for (int j = 0; j < i - 1 && j < dp.length; ++j) {
      sum += dp[j] * binomialCoefficient(i - 1, j);
    }
    dp.add(sum);
  }
  return dp;
}

int binomialCoefficient(int n, int k) {
  if (k > n) return 0;
  if (k == 0 || k == n) return 1;
  final half = min(k, n - k);
  int result = 1;
  for (int i = 1; i <= half; ++i) {
    result *= (n - i + 1) ~/ i;
  }
  return result;
}
