import 'dart:math';

List<int> f(int n) {
  if (n == 0) return [1];

  List<int> result = [];
  int count = 0;

  for (int i = 2; i <= n * n; i++) {
    bool isPrime = true;

    // Check divisibility from 2 to sqrt(i)
    for (int j = 2; j <= sqrt(i); j++) {
      if (i % j == 0) {
        isPrime = false;
        break;
      }
    }

    if (isPrime) {
      int sumOfDivisors = 0;

      // Calculate the sum of divisors
      for (int k = 1; k <= i / 2; k++) {
        if (i % k == 0) {
          sumOfDivisors += k;
        }
      }

      sumOfDivisors += i;

      // If the sum equals n, add this prime number to the list
      if (sumOfDivisors == n) {
        result.add(i);
        count++;

        // Early exit if we've found all required primes
        if (count >= n) break;
      }
    }
  }

  return result;
}
