bool moveOneBall(List<int> arr) {
  int n = arr.length;
  if (n == 0 || n < 3) return false;

  // Check for any three consecutive elements that form a valid operation
  for (int i = 1; i < n - 1; ++i) {
    if (arr[i] != arr[i-1] && arr[i] != arr[i+1]) {
      // Perform the swap and check if it's possible to reach target
      List<int> copy = [...arr];
      if (copy[i-1] != copy[i] && copy[i] != copy[i+1]) {
        // Swap with left or right, whichever is different
        if (copy[i-1] == copy[i+1]) {
          copy[i] = copy[i-1]; // swap with left
        } else {
          copy[i] = copy[i+1]; // swap with right
        }

        // Now check if this leads us closer to forming all same numbers
        // We need to ensure after each such step we have at least one more ball of another type
        bool canContinue = true;
        while (canContinue) {
          canContinue = false;
          for (int j = 1; j < n - 1; ++j) {
            if (copy[j] != copy[j-1] && copy[j] != copy[j+1]) {
              if (copy[j-1] == copy[j+1]) {
                copy[j] = copy[j-1];
              } else {
                copy[j] = copy[j+1];
              }
              canContinue = true;
            }
          }
        }

        // After performing these swaps, check if all are equal
        bool allEqual = true;
        for (int k = 1; k < n; ++k) {
          if (copy[k] != copy[0]) {
            allEqual = false;
            break;
          }
        }
        return allEqual;
      }
    }
  }

  return false;
}
