List<Object> reverseDelete(String s, String c) {
  List<String> result = [];

  for (int i = 0; i < s.length; i++) {
    if (s[i] != c[0]) {
      // Check if the current character is not equal to 'c'
      result.add(s[i]);
    } else {
      // If it's equal, check whether there are more characters in 'c' that match
      bool foundMatch = false;
      for (int j = 1; j < c.length && !foundMatch; j++) {
        if (i + j >= s.length || s[i + j] != c[j]) {
          break;
        }
        foundMatch = true;
      }

      if (!foundMatch) {
        // No matching subsequence found, add the previous part of 's'
        int k = i - 1;
        while (k >= 0 && s[k] == c[c.length - 1]) {
          k--;
        }

        if (k >= 0) {
          result.addAll(List.generate(k + 1, (_) => s[0]));
        }

        // Add any remaining characters after the deleted part
        int l = i + c.length - 1;
        while (l < s.length) {
          result.add(s[l++]);
        }
      }
    }
  }

  return result.map((e) => e as Object).toList();
}
