  final result = <Object>[];
  Queue<String> queue = Queue();
  queue.add(s);

  while (!queue.isEmpty) {
    final current = queue.removeFirst();

    // If the string contains the character
    if (current.contains(c)) {
      // Remove all occurrences of 'c' from the string and add to queue
      final newStr = current.replaceAll(c, '');
      queue.add(newStr);

      // Add the modified string to results
      result.add(newStr);
    } else {
      // No more removal possible for this string
    }
  }

  return result;
