  int n = nums.length;
  if (n == 0) return 0;

  // Initialize with the first element and a minimum sum of positive infinity
  int currentSum = nums[0];
  int minSum = double.infinity;

  for (int i = 1; i < n; i++) {
    // If adding the next number makes the currentSum negative, reset it to zero
    if (currentSum + nums[i] > nums[i]) {
      currentSum += nums[i];
    } else {
      currentSum = nums[i]; // Start new subarray from nums[i]
    }

    // Update the minimum sum found so far
