      if (totalSum <= capacity) {
        result[currentRow][col] = 1;
        col++;
        currentRow = 0;
        continue;
      }

      // If not enough capacity, backtrack by one row up
      currentRow--;
      if (currentRow >= 0) { 
        totalSum -= grid[currentRow + 1][col]; 
      } else break; // No more rows to backtrack
    }

    // Reset currentRow after processing each column
    currentRow = 0;
  }

  // Count filled cells in result matrix
  int count = 0;
  for (final row in result) {
    for (final val in row) {
      if (val != -1) count++;
    }
  }

  return count;
}
```

This implementation follows a greedy approach where it fills as much as possible from top-left to bottom-right. It uses an auxiliary `result` matrix to track which cells are filled.

The algorithm works by:
- Starting at the first row.
- For each column, accumulating values until adding another element would exceed the capacity.
- Filling that cell when there's sufficient remaining capacity.
- When exceeding capacity, backtracking by one row and adjusting the sum accordingly.

The solution efficiently processes all elements without needing any additional data structures beyond the result matrix, achieving O(n*m) time complexity where n is number of rows and m columns.

```dart
import 'dart:math';

int maxFill(List<List<int>> grid, int capacity) {
  final rows = grid.length;
  if (rows == 0) return 0;
  final cols = grid[0].length;

  // Directions for the four directions (up, down, left, right)
  const dirs = <List<int>>[
    [-1, 0], [1, 0], [0, -1], [0, 1]
  ];

  var visited = List<bool>.filled(rows * cols, false);
  var queue = Queue();

  // Start from all cells with value 0 as initial "empty" spaces.
  for (var r = 0; r < rows; r++) {
    for (var c = 0; c < cols; c++) {
      if (grid[r][c] == 0 && !visited[r * cols + c]) {
        queue.add([r, c]);
        visited[r * cols + c] = true;
      }
    }
  }

  while (queue.isNotEmpty) {
    var cell = queue.removeFirst();
    var r = cell[0];
    var c = cell[1];

    for (final dir in dirs) {
      var nr = r + dir[0];
      var nc = c + dir[1];
      if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&
          !visited[nr * cols + nc] && grid[nr][nc] == 0) {
        visited[nr * cols + nc] = true;
        queue.add([nr, nc]);
      }
    }
  }

  var filledCount = 0;
  for (var i = 0; i < rows * cols; i++) {
    if (!visited[i]) {
      filledCount++;
    }
  }

  return min(filledCount, capacity);
}
