int maxFill(List<List<int>> grid, int capacity) {
  final rows = grid.length;
  if (rows == 0) return 0;
  final cols = grid[0].length;

  // Initialize a priority queue to keep track of the maximum possible fill in each row.
  List<int> pq = [];

  for (var i = 0; i < rows; ++i) {
    var sumRow = 0;
    for (var j = 0; j < cols; ++j) {
      sumRow += grid[i][j];
    }
    pq.add(sumRow);
  }

  pq.sort((a, b) => b.compareTo(a)); // Sort descending

  int total = 0;

  while (capacity > 0 && pq.isNotEmpty) {
    final currentMax = pq.removeAt(0); // Get the largest row's sum
    final remainingCapacity = capacity - currentMax;

    if (remainingCapacity >= 0) {
      total += currentMax;
      capacity -= currentMax;
    } else {
      // We can only take part of this row
      // Find how much we can add from this row without exceeding capacity
      final amountToTake = min(currentMax, capacity);
      total += amountToTake;
      capacity -= amountToTake;
    }

    // Reinsert the updated value back into the heap
    pq.add(currentMax - amountToTake);

    // Keep the heap size at its original length by removing the smallest element
    pq.sort(); // This is O(n log n), but given that the number of elements is small, it's acceptable
  }

  return total;
}
