int maxFill(List<List<int>> grid, int capacity) {
  final rows = grid.length;
  if (rows == 0) return 0;

  final cols = grid[0].length;
  if (cols == 0) return 0;

  final visited = List.generate(rows, (_) => List.filled(cols, false));
  final directions = [[-1, 0], [1, 0], [0, -1], [0, 1]]; // up, down, left, right

  void dfs(int x, int y, int currentCapacity) {
    if (x < 0 || x >= rows || y < 0 || y >= cols || visited[x][y] || currentCapacity <= 0) return;

    visited[x][y] = true;

    for (final dir in directions) {
      final newX = x + dir[0];
      final newY = y + dir[1];

      if (newX >= 0 && newX < rows && newY >= 0 && newY < cols && !visited[newX][newY]) {
        dfs(newX, newY, min(currentCapacity, grid[newX][newY]));
      }
    }

    final newCapacity = currentCapacity - grid[x][y];
    if (newCapacity > 0) {
      dfs(x, y, newCapacity);
    }
  }

  var result = 0;
  for (var i = 0; i < rows; i++) {
    for (var j = 0; j < cols; j++) {
      if (!visited[i][j]) {
        dfs(i, j, capacity);
        result += grid[i][j];
      }
    }
  }

  return result;
}
