List<int> sortArray(List<int> arr) {
  if (arr.isEmpty || arr.length == 1) return List.from(arr);

  int n = arr.length;
  Random random = Random();

  // Randomized quicksort implementation
  void _quicksort(int low, int high) {
    if (low >= high) return;

    int pivotIndex = low + random.nextInt(high - low);
    int pivot = arr[pivotIndex];
    int left = low;
    int right = high;

    while (left < right) {
      while (left < right && arr[left] < pivot) left++;
      while (left < right && arr[right] > pivot) right--;

      if (left < right) {
        int temp = arr[left];
        arr[left] = arr[right];
        arr[right] = temp;
        left++;
        right--;
      }
    }

    _quicksort(low, right);
    _quicksort(right + 1, high);
  }

  _quicksort(0, n - 1);
  return arr;
}

