List<String> selectWords(String s, int n) {
  final words = s.split(' ').toList();
  if (words.isEmpty || n <= 0) return [];

  // Handle cases where n is larger than the number of words.
  final effectiveN = min(n, words.length);

  // Rotate list to bring first [effectiveN] elements to end.
  final rotated = rotateLeft(words, effectiveN).take(effectiveN).toList();

  return rotated;
}

// Helper function from collection package.
List<T> rotateLeft<T>(List<T> list, int count) {
  if (count == 0) return list;

  final length = list.length;
  final adjustedCount = count % length;
  return list.getRange(length - adjustedCount, length)
      .concat(list.take(length - adjustedCount));
}
