String getClosestVowel(String word) {
  final vowels = ['a', 'e', 'i', 'o', 'u'];
  int closestIndex = -1;
  int minDistance = int.maxValue;

  for (int i = 0; i < word.length; i++) {
    if (vowels.contains(word[i].toLowerCase())) {
      // Calculate the distance from current index to the nearest vowel
      final distanceToPrev = (i - closestIndex).abs();
      final distanceToNext = (closestIndex != -1 ? (i - closestIndex) : int.maxValue);

      if (distanceToPrev <= minDistance && distanceToNext >= distanceToPrev) {
        minDistance = distanceToPrev;
        closestIndex = i;
      }
    } else {
      // If not a vowel, check if it's between two vowels and update accordingly
      int prevIndex = -1;
      int nextIndex = -1;
      for (int j = i - 1; j >= 0; j--) {
        if (vowels.contains(word[j].toLowerCase())) {
          prevIndex = j;
          break;
        }
      }
      for (int k = i + 1; k < word.length; k++) {
        if (vowels.contains(word[k].toLowerCase())) {
          nextIndex = k;
          break;
        }
      }

      if (prevIndex == -1 && nextIndex == -1) continue; // No vowels nearby

      if (prevIndex == -1) {
        // Only next vowel is present
        if ((nextIndex - i) < minDistance) {
          minDistance = nextIndex - i;
          closestIndex = nextIndex;
        }
      } else if (nextIndex == -1) {
        // Only previous vowel is present
        if ((i - prevIndex) < minDistance) {
          minDistance = i - prevIndex;
          closestIndex = prevIndex;
        }
      } else {
        // Both vowels exist around this position
        int leftDist = i - prevIndex;
        int rightDist = nextIndex - i;

        if (leftDist < rightDist || (leftDist == rightDist && prevIndex > nextIndex)) {
          if (leftDist < minDistance) {
            minDistance = leftDist;
            closestIndex = prevIndex;
          }
        } else {
          if (rightDist < minDistance) {
            minDistance = rightDist;
            closestIndex = nextIndex;
          }
        }
      }
    }
  }

  return word[closestIndex] ?? '';
}

