          (currentDistance == minDistance && pos > closestIndex)) {
        minDistance = currentDistance;
        closestIndex = pos;
      }
    }
  }

  // If no vowels found, return ''
  if (closestIndex == -1) return '';

  // Return the character at the closest position
  return word[closestIndex].toString();
}

