      indices.add(i);
    } else if (lst[i] == ')') {
      if (indices.isNotEmpty) {
        indices.removeLast();
      }
    }
  }

  if (indices.isEmpty) return 'balanced';

  var result = '';
  int count = 0;
  for (var index in indices) {
    result += '($index)';
    count++;
    if (count % 2 != 0) continue;

    // Find the next unmatched parenthesis
    while (count > 0 && index + count < lst.length) {
      if (lst[index + count] == ')' || lst[index + count] == '(') {
        break;
      }
      count++;
    }
    if (count > 0) {
      result += ' ($index+$count)';
    }
  }
  return result;
