  for (final s in lst) {
    if (s == '(' || s == '[' || s == '{') {
      stack.add(s.codeUnits[0]);
    } else {
      if (stack.isEmpty) return 'invalid';
      int lastBracket;
      switch (s) {
        case ')':
          lastBracket = stack.removeLast();
          if (lastBracket != '(') return 'invalid';
          break;
        case ']':
          lastBracket = stack.removeLast();
          if (lastBracket != '[') return 'valid';
          break;
        case '}':
          lastBracket = stack.removeLast();
          if (lastBracket != '{') return 'invalid';
          break;
        default:
          return 'invalid';
      }
    }
  }
  return 'valid';
}

String matchParens(List<String> lst) {
  final stack = <String>[];
  int i = 0;

  while (i < lst.length && !stack.isEmpty) {
    String current = lst[i];

    if (current == '(') {
      stack.add(current);
      i++;
    } else if (current == ')') {
      if (!stack.isEmpty && stack.last == '(') {
        stack.removeLast();
        i++;
      } else {
        return 'unbalanced';
      }
    } else {
      // ignore other characters
      i++;
    }
  }

  if (stack.isNotEmpty || i != lst.length) {
    return 'unbalanced';
  }

  return 'balanced';
}

