import 'dart:math';

List<int> maximum(List<int> arr, int k) {
  if (arr.isEmpty || k <= 0 || k >= arr.length) return List.filled(arr.length, -1);

  final n = arr.length;
  final maxHeap = List<int>.filled(n, 0);

  for (int i = 0; i < n; i++) {
    maxHeap[i] = arr[i];
  }

  _buildMaxHeap(maxHeap, n);

  final result = List<int>.filled(k, 0);

  for (int i = 0; i < k; i++) {
    result[i] = maxHeap[0];
    maxHeap[0] = maxHeap[n - 1 - i];
    n--;
    _maxHeapify(maxHeap, 0, n);
  }

  return result;
}

void _buildMaxHeap(List<int> heap, int size) {
  for (int i = (size ~/ 2) - 1; i >= 0; i--) {
    _maxHeapify(heap, i, size);
  }
}

void _maxHeapify(List<int> heap, int index, int size) {
  var largest = index;
  final left = 2 * index + 1;
  final right = 2 * index + 2;

  if (left < size && heap[left] > heap[largest]) {
    largest = left;
  }

  if (right < size && heap[right] > heap[largest]) {
    largest = right;
  }

  if (largest != index) {
    swap(heap, index, largest);
    _maxHeapify(heap, largest, size);
  }
}

void swap(List<int> list, int a, int b) {
  final temp = list[a];
  list[a] = list[b];
  list[b] = temp;
}
