    if (n % 2 == 0) {
      // If even, divide by two
      n ~/= 2;
    } else {
      // If odd, apply the formula
      n = (3 * n) + 1;
    }

    result.add(n);
  }

  return List<int>.from(result.where((element) => element.isOdd));
}

