List<int> minPath(List<List<int>> grid, int k) {
  final rows = grid.length;
  if (rows == 0) return [];
  final cols = grid[0].length;

  // Initialize a priority queue for Dijkstra's algorithm
  final pq = PriorityQueue<QueueElement>();

  // Each element in the priority queue will be of form: (cost, row, col)
  pq.add(QueueElement(0, 0, 0));

  final visited = List.generate(rows, (_) => List<bool>.filled(cols, false));
  final dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]]; // up, down, left, right

  while (!pq.isEmpty) {
    final current = pq.removeFirst();

    final cost = current.cost;
    final r = current.row;
    final c = current.col;

    if (r < 0 || r >= rows || c < 0 || c >= cols) continue;
    if (visited[r][c]) continue;

    visited[r][c] = true;

    if (grid[r][c] > k) {
      // If cell value exceeds k, skip it as we can't take this path
      continue;
    }

    // Check if reached bottom-right corner
    if (r == rows - 1 && c == cols - 1) {
      return [current.cost];
    }

    for (final dir in dirs) {
