import 'dart:math';

bool isNested(String string) {
  final List<String> brackets = ['(', ')', '{', '}', '[', ']'];
  int depth = 0;

  for (final char in string.split('')) {
    if (brackets.contains(char)) {
      // Check if the bracket matches
      bool match = false;
      var index = brackets.indexOf(char);

      while (index >= 0 && !match) {
        switch (char) {
          case '(':
            if (depth > 0 && brackets[index + 1] == ')' || 
                depth > 0 && brackets[index - 2] == ')' ||
                depth > 0 && brackets[index + 3] == ')' || 
                depth > 0 && brackets[index - 4] == ')') {
              match = true;
            }
            break;
          case ')':
            if (depth > 0 && brackets[index - 1] == '(') {
              match = true;
            }
            break;
          case '[':
            if (depth > 0 && brackets[index + 5] == ']' || 
                depth > 0 && brackets[index - 6] == ']' || 
                depth > 0 && brackets[index + 7] == ']' || 
                depth > 0 && brackets[index - 8] == ']') {
              match = true;
            }
            break;
          case ']':
            if (depth > 0 && brackets[index - 9] == '[') {
              match = true;
            }
            break;
          default:
            match = false;
        }

        index -= 3; // Move to next possible matching pair
      }

      if (!match) return false;

      // Update depth based on opening or closing bracket
      if (char == '(' || char == '[' || char == '{') {
        depth++;
      } else {
        depth--;
        if (depth < 0) return false;
      }
    }
  }

  return depth == 0;
}
