import 'dart:math';

int canArrange(List<int> arr) {
  // If the array has less than two elements, no arrangement is needed
  if (arr.isEmpty || arr.length == 1) {
    return 0;
  }

  int count = 0;

  // Iterate through the array from index 0 to n-2
  for (var i = 0; i < arr.length - 1; i++) {
    // Check if the sum of current element and next one is odd
    if ((arr[i] + arr[i + 1]) % 2 != 0) {
      count++;
    }
  }

  // Return 1 if there are at least three such pairs with odd sums, otherwise return 0
  return count >= 3 ? 1 : 0;
}

