bool isEqualToSumEven(int n) {
  if (n < 0 || n == 1) return false;

  int sum = 0;
  for (int i = 2; i <= sqrt(n); i++) {
    if (n % i == 0) {
      sum += i;
      if (i != n / i) {
        sum += n ~/ i;
      }
    }
  }

  // Add the number itself only if it's not a perfect square to avoid double-counting
  if (!isPerfectSquare(n)) {
