String fixSpaces(String text) {
  final lines = text.split('\n');
  String fixedText = '';

  for (int i = 0; i < lines.length; i++) {
    final line = lines[i];

    // Check if the current line is not empty and has a trailing space or tab
    bool shouldTrim = false;
    if (line.isNotEmpty && line.trim().isNotEmpty) {
      int lastNonWhitespaceIndex = -1;
      for (int j = 0; j < line.length; j++) {
        if (!line[j].trim().isEmpty) {
          lastNonWhitespaceIndex = j;
        }
      }

      if (lastNonWhitespaceIndex != -1 && line[lastNonWhitespaceIndex] == ' ') {
        shouldTrim = true;
      }
    }

    if (shouldTrim) {
      // Trim only spaces at the end of the line, preserving other whitespace
      final trimmedLine = line.replaceAll(RegExp(r'[ \t]+$'), '');
      fixedText += '$trimmedLine\n';
    } else {
      fixedText += '$line\n';
    }
  }

  return fixedText.trimEnd();
}
