import 'package:collection/collection.dart';

bool simplify(String x, String n) {
  final xDigits = List<int>.from(x.codeUnits.map((c) => c - '0'.codeUnitAt(0)));
  final nDigits = List<int>.from(n.codeUnits.map((c) => c - '0'.codeUnitAt(0)));

  if (x.length != n.length || x.isEmpty || n.isEmpty) return false;

  for (var i = 0; i < x.length; ++i) {
    final xDigit = xDigits[i];
    final nDigit = nDigits[i];

    if (xDigit == nDigit) continue;
    if (xDigit > nDigit) return false;
  }

  // Check that all digits in x are less than or equal to corresponding ones in n
  var isSimplified = true;
  for (int i = 0; i < x.length && isSimplified; ++i) {
    if (xDigits[i] > nDigits[i]) {
      isSimplified = false;
      break;
    }
  }

  return isSimplified;
}
