  int b = int.parse(n);

  if (b == 0) return false;

  while (a % b != 0 || b % a != 0) {
    final gcd = _gcd(a, b);
    a ~/= gcd;
    b ~/= gcd;

    if (a < 0) a *= -1;
    if (b < 0) b *= -1;

    if (a == 0 && b > 0) break; // Prevent infinite loop when a is zero

    if (a == 1 && b == 1) break;
  }

  return a == 1 && b == 1;
}

int _gcd(int a, int b) {
  while (b != 0) {
    final temp = b;
    b = a % b;
    a = temp;
  }
  return a;
