List<int> orderByPoints(List<int> nums) {
  if (nums.isEmpty) return [];

  // Pair each number with its index to keep track of original positions
  List<Map<String, int>> indexedNums = nums.asMap().entries.map((entry) => {'num': entry.value, 'index': entry.key}).toList();

  // Sort the list based on the value of the numbers in ascending order
  indexedNums.sort((a, b) => a['num'] - b['num']);

  // Extract the sorted indices and map them back to the original array
  List<int> resultIndices = indexedNums.map((e) => e['index']).toList();

  return resultIndices;
}
