List<int> orderByPoints(List<int> nums) {
  List<int> result = [];

  // Count frequency of each number
  Map<int, int> freqMap = {};
  for (int num in nums) {
    if (!freqMap.containsKey(num)) {
      freqMap[num] = 0;
    }
    freqMap[num]++;
  }

  // Generate list with elements sorted by their count and value
  List<int> keys = freqMap.keys.toList();
  keys.sort((a, b) {
    var countA = freqMap[a];
    var countB = freqMap[b];

    if (countA != countB) {
      return countB - countA; // Sort descending order based on counts
    } else {
      return a.compareTo(b); // If same count, sort ascending by value
    }
  });

  // Build the result list as per the sorted key values
  for (int key in keys) {
    final count = freqMap[key];
    for (var i = 0; i < count; i++) {
      result.add(key);
    }
  }

  return result;
}

