  int correctPosition = 0;
  int incorrectPosition = 0;

  if (game.length != guess.length || game.isEmpty || guess.isEmpty) {
    return [correctPosition, incorrectPosition];
  }

  final Map<int, int> gameCount = {};
  for (int num in game) {
    gameCount[num] = (gameCount[num] ?? 0) + 1;
  }

  for (int i = 0; i < guess.length; i++) {
    final guessedNum = guess[i];
    final gameNum = game[i];

    if (guessedNum == gameNum) {
      correctPosition++;
    } else if (gameCount.containsKey(guessedNum)) {
      // Check if the number is present and not already counted as a correct position
      if (gameCount[guessedNum]! > 0 && !gameCount[guessedNum]!.isNegative) {
        incorrectPosition++;
        gameCount[guessedNum] = gameCount[guessedNum!] - 1;
      }
    }
  }

  return [correctPosition, incorrectPosition];
}
