        lowerLetters++;
      } else if ('A' <= c && c <= 'Z') {
        upperLetters++;
      }
    }

    // Score is calculated based on the difference between lowercase and uppercase counts
    score += lowerLetters - upperLetters;

    // Add a bonus for having more than one unique character (to avoid simple names like "a")
    if (ext.replaceAll(RegExp('[A-Z]'), '').length > 1) {
      score += 2; // Additional points for complexity
    }

    extensionScores[ext] = score;
  }

  // Find the extension with the highest score
  String? bestExt;
  int maxScore = -Infinity;
  for (final entry in extensionScores.entries) {
    if (entry.value > maxScore) {
      maxScore = entry.value;
      bestExt = entry.key;
    }
  }

  return bestExt ?? '';
}
