String strongestExtension(String className, List<String> extensions) {
  if (extensions.isEmpty || extensions.length == 1) return '';

  int maxScore = -1;
  String bestExt = '';

  for (var ext in extensions) {
    var parts = ext.split('.');
    if (parts[0] != className) continue; // Only consider extensions of the class

    int score = 0;

    // Check strength based on number of characters
    score += parts[1].length * 5; // Longer names are stronger

    // Check alphabetical order
    bool isAlphabetical = true;
    for (int i = 1; i < parts.length-1; i++) {
      if (parts[i+1].compareTo(parts[i]) <= 0) {
        isAlphabetical = false;
        break;
      }
    }
    if (isAlphabetical) score += 30; // Alphabetical ordering adds bonus points

    // Check for numeric suffixes at end
    if (RegExp(r'^\d+$').hasMatch(parts.last)) {
      int numSuffix = int.parse(parts.last);
      if (numSuffix > maxScore && numSuffix >= 10) { 
        score += 20 + numSuffix * 2; // Higher numbers add more value
      } else if (numSuffix >= 1) {
        score -= 5; // Small numbers have some penalty
      }
    }

    // Special case: 'final' extension gives major boost
    if (ext == '${className}.final') {
      score += 100;
    }

    if (score > maxScore) {
      maxScore = score;
      bestExt = ext;
    }
  }

  return bestExt;
}

