  for (var ext in extensions) {
    final name = ext.split('.').last; // Extract extension name
    final power = _calculateStrength(name);

    if (power > maxPower || (power == maxPower && name.compareTo(strongestExt) < 0)) {
      maxPower = power;
      strongestExt = name;
    }
  }

  return '$className.$strongestExt';
}

int _calculateStrength(String name) {
  int letterScore = 0;
  int digitCount = 0;

  for (final c in name.codeUnits) {
    if ('a' <= c.toString().toLowerCase() && 'z' >= c.toString().toLowerCase()) {
      letterScore += c - 'a' + 1;
    } else if (c.toString().isDigit()) {
      digitCount++;
    }
  }

  return letterScore * 256 + digitCount * 73;
}

