bool rightAngleTriangle(num a, num b, num c) {
  // Ensure all sides are positive to avoid negative values.
  if (a <= 0 || b <= 0 || c <= 0) return false;

  // Calculate the squares of each side.
  final aSquared = pow(a, 2);
  final bSquared = pow(b, 2);
  final cSquared = pow(c, 2);

  // Check Pythagorean theorem with tolerance for floating-point errors.
  const double epsilon = 1e-9;
  final isRightAngle = (abs((aSquared + bSquared) - cSquared) < epsilon) ||
      (abs((aSquared + cSquared) - bSquared) < epsilon) ||
      (abs((bSquared + cSquared) - aSquared) < epsilon);

  return isRightAngle;
}
```

