String solve(String s) {
  if (s == '') return '';

  int n = s.length;
  List<String> result = [];
  String currentWord = '';

  for (int i = 0; i < n; i++) {
    final char = s[i];

    // Check if the character is a lowercase letter
    if ('a' <= char && 'z' >= char) {
      currentWord += char;
    } else {
      // If it's not, add to result and reset currentWord
      result.add(currentWord);
      currentWord = '';

      // Handle special case: if it's an apostrophe or space, just add as is
      if (char != '\'' && char != ' ') {
        result.add(char);
      }
    }
  }

  // Add the last word in the loop
  if (currentWord.isNotEmpty) {
    result.add(currentWord);
  }

  // Join all parts with spaces and convert to uppercase
  return result.join(' ').toUpperCase();
}
