String solve(String s) {
  if (s.isEmpty || s.length == 1) return s;

  int n = s.length;
  List<int> dp = List.filled(n, 0);

  for (int i = 0; i < n - 1; i++) {
    dp[i] = 1 + (i > 0 ? dp[i-1] : 0);
  }

  for (int i = n - 2; i >= 0; i--) {
    if (s[i] == s[n-1]) {
      dp[i] = 1 + (i > 0 ? dp[i-1] : 0);
    } else {
      dp[i] = max(dp[i], dp[i+1]);
    }
  }

  return dp[0].toString();
}
